#!/usr/bin/env sh
# Sheriff pig in the inferno: ANSI truecolor half-block art, like thisisfine.sh.
# Generated by scripts/pig-ui/generate-art.py; edit the generator to change art.
set -eu

# Keep color when captured by a UI component, just like thisisfine.sh.
color=1
[ -z "${NO_COLOR+x}" ] || color=0
case "${1:-}" in
  --color) color=1 ;;
  --no-color) color=0 ;;
  --help|-h)
    printf '%s\n' 'Usage: pig-is-fine.sh [--color|--no-color]' \
      'Sheriff pig in flames. Requires a UTF-8 terminal; truecolor recommended.'
    exit 0 ;;
  '') ;;
  *) printf 'Unknown option: %s\n' "$1" >&2; exit 2 ;;
esac
if [ "$#" -gt 1 ]; then
  printf '%s\n' 'Expected at most one option. Use --help.' >&2
  exit 2
fi

awk -v color="$color" '
BEGIN {
  esc = sprintf("%c", 27)
  palette["r"] = "189;65;24"
  palette["o"] = "209;85;28"
  palette["f"] = "224;112;33"
  palette["a"] = "235;151;28"
  palette["y"] = "247;192;52"
  palette["l"] = "255;218;96"
  palette["k"] = "53;33;29"
  palette["h"] = "132;78;43"
  palette["t"] = "185;122;62"
  palette["s"] = "223;164;89"
  palette["p"] = "239;151;165"
  palette["q"] = "255;186;194"
  palette["v"] = "204;103;129"
  palette["n"] = "170;75;101"
  palette["w"] = "255;241;209"
  palette["b"] = "170;53;43"
  palette["c"] = "218;79;55"
  palette["d"] = "109;61;38"
}
NR % 2 { upper = $0; next }
{
  for (x = 1; x <= length($0); x++) {
    top = substr(upper, x, 1)
    bottom = substr($0, x, 1)
    if (color) {
      fg = top == "." ? "39" : "38;2;" palette[top]
      bg = bottom == "." ? "49" : "48;2;" palette[bottom]
      printf "%s[%s;%sm", esc, fg, bg
      if (top == ".") {
        if (bottom == ".") printf " "
        else printf "%s[38;2;%s;49m▄", esc, palette[bottom]
      } else printf "▀"
    } else {
      if (top == "." && bottom == ".") printf " "
      else if (top == ".") printf "▄"
      else if (bottom == ".") printf "▀"
      else printf "█"
    }
  }
  if (color) printf "%s[0m", esc
  printf "\n"
}
